import{_ as t,o,c as a,a2 as i}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Diagnostic","description":"","frontmatter":{"title":"Diagnostic"},"headers":[],"relativePath":"en/reference/diagnostic.md","filePath":"en/reference/diagnostic.md"}'),d={name:"en/reference/diagnostic.md"};function n(s,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="diagnostic-machine-state-and-the-ceiling" tabindex="-1">Diagnostic: machine state and the ceiling <a class="header-anchor" href="#diagnostic-machine-state-and-the-ceiling" aria-label="Permalink to &quot;Diagnostic: machine state and the ceiling&quot;">​</a></h1><p>Two read-only tools that change nothing and open no session. They are not subject to the ceiling.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Role</th></tr></thead><tbody><tr><td><a href="#daimon-doctor"><code>daimon_doctor</code></a></td><td>Diagnosis of the whole machine, organ by organ</td></tr><tr><td><a href="#main-ceiling"><code>main_ceiling</code></a></td><td>Active authorization ceiling of Mains (Hands)</td></tr><tr><td><a href="#ping"><code>ping</code></a></td><td>Health check (appendix)</td></tr></tbody></table><h2 id="daimon-doctor" tabindex="-1">daimon_doctor <a class="header-anchor" href="#daimon-doctor" aria-label="Permalink to &quot;daimon_doctor {#daimon-doctor}&quot;">​</a></h2><p>Returns the state of <strong>every</strong> organ in a single call. <strong>Call it first</strong> when something behaves strangely, and before concluding that a tool is broken.</p><p><strong>Parameters</strong>: none. <strong>Level</strong>: read.</p><p><strong>Example call</strong>: <code>daimon_doctor</code> with no arguments.</p><p><strong>Returns</strong>: a structured object. The top-level keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Content</th></tr></thead><tbody><tr><td><code>ok</code></td><td>Overall verdict: reliable probes, Screen Recording and Accessibility granted, nothing broken</td></tr><tr><td><code>backend</code></td><td>Kind of the permissions probe (<code>kind</code>), its reliability (<code>trustworthy</code>) and a note</td></tr><tr><td><code>responsible_app</code></td><td>The responsible application, the one the system attaches the permissions to</td></tr><tr><td><code>permissions</code></td><td>Actual verdict for <code>screen_recording</code> and <code>accessibility</code> (<code>granted</code>, affected tools)</td></tr><tr><td><code>exclusions</code></td><td>State of the exclusions file</td></tr><tr><td><code>organs</code></td><td>State of each organ</td></tr><tr><td><code>overlay</code></td><td>State of the Overlay helper (see below)</td></tr><tr><td><code>consequences</code></td><td>What each missing permission concretely does to each tool</td></tr><tr><td><code>ceiling</code></td><td>Active ceiling, in the format of <code>main_ceiling</code></td></tr><tr><td><code>cannot_detect</code></td><td>What the diagnosis <strong>cannot</strong> detect</td></tr><tr><td><code>next</code></td><td>Suggested next steps</td></tr></tbody></table><p><strong>The <code>overlay</code> key</strong> describes the process that draws the <a href="./overlay.html">Overlay</a>, without ever connecting to it:</p><table tabindex="0"><thead><tr><th>Sub-key</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>The &quot;Présence à l&#39;écran&quot; (Presence on screen) setting is enabled</td></tr><tr><td><code>socket_present</code></td><td>boolean</td><td>The helper&#39;s socket file exists (it may be stale)</td></tr><tr><td><code>lock_held</code></td><td>boolean</td><td>A helper holds the lock: it is alive</td></tr><tr><td><code>listening</code></td><td>boolean</td><td><code>socket_present</code> and <code>lock_held</code> together: the helper is alive and listening</td></tr><tr><td><code>last_log_line</code></td><td>string or <code>null</code></td><td>Last line of <code>overlay.log</code>, truncated to 200 characters; <code>null</code> if the log is absent or unreadable</td></tr></tbody></table><p>Example of a helper that stopped cleanly:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;socket_present&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;listening&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;lock_held&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;last_log_line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-16T07:50:27Z overlay: exit reason=idle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>This key affects neither <code>ok</code>, nor <code>next</code>, nor <code>consequences</code>.</p><p><strong>Pitfalls</strong></p><ul><li>Verdicts are probed in the current process, through APIs that never ask for permission: running it cannot make a dialog appear.</li><li>Read <code>consequences</code>: without Accessibility, <code>main_type</code>, <code>main_key</code>, <code>main_hover</code> and <code>main_navigate</code> return <code>status: &quot;done&quot;</code> as silent no-ops, and <code>main_click</code>, <code>main_press</code>, <code>main_drag</code> wait 30 seconds for a confirmation dialog.</li><li>Also read <code>cannot_detect</code>: a reported absence of problems is not proof for what is listed there.</li></ul><h2 id="main-ceiling" tabindex="-1">main_ceiling <a class="header-anchor" href="#main-ceiling" aria-label="Permalink to &quot;main_ceiling {#main-ceiling}&quot;">​</a></h2><p>A read-only snapshot of the active authorization ceiling of Mains: the current level, whether L4 is active, the nominal level of each action tool and those currently refused because they are above the ceiling. It is the tool to call before driving, to announce up front what you will not be able to do rather than being refused along the way.</p><p><strong>Parameters</strong>: none. <strong>Level</strong>: read.</p><p><strong>Example call</strong>: <code>main_ceiling</code> with no arguments.</p><p><strong>Returns</strong></p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Content</th></tr></thead><tbody><tr><td><code>ceiling</code></td><td>string</td><td>Active ceiling: <code>READ</code>, <code>NONDESTRUCTIVE</code>, <code>INPUT</code>, <code>VALIDATION</code> or <code>AUTONOMOUS</code></td></tr><tr><td><code>l4_active</code></td><td>boolean</td><td>True when the ceiling is <code>AUTONOMOUS</code> (L4)</td></tr><tr><td><code>levels</code></td><td>object</td><td>Name of each action tool mapped to its nominal level</td></tr><tr><td><code>gated_above</code></td><td>list of strings</td><td>Tools refused at the current ceiling, sorted alphabetically</td></tr></tbody></table><p>Mapping to the L0 to L4 convention: <code>READ</code> = L0, <code>NONDESTRUCTIVE</code> = L1, <code>INPUT</code> = L2, <code>VALIDATION</code> = L3, <code>AUTONOMOUS</code> = L4. Tool levels are detailed on the <a href="./mains.html#niveaux">Mains</a> page.</p><p><strong>Pitfalls</strong></p><ul><li>A ceiling that exceeds a tool&#39;s level allows it, but the target can still raise the effective level: the tool&#39;s absence from <code>gated_above</code> does not guarantee that every call will go through.</li><li>A malformed configuration or a missing log degrades to safe values, without error: the report is always returned.</li><li>The ceiling is a human setting: no tool lets the AI raise it.</li></ul><h2 id="ping" tabindex="-1">ping <a class="header-anchor" href="#ping" aria-label="Permalink to &quot;ping {#ping}&quot;">​</a></h2><p>Health check: always returns the literal string <code>pong</code>. No parameters.</p>`,27)])])}const k=t(d,[["render",n]]);export{g as __pageData,k as default};
